sys_script_include.script:
var MgrHubAjax = Class.create();
MgrHubAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    /** Returns JSON: { valid, daysToDue, leadDays } */
    getDueInfo: function() {
        var utils = new MgrHubUtils();
        var dueDate = this._toInternal(this.getParameter('sysparm_due_date'));
        var openedAt = this._toInternal(this.getParameter('sysparm_opened_at'));

        if (!dueDate)
            return JSON.stringify({
                valid: true,
                daysToDue: null,
                leadDays: null
            });

        var check = utils.validateDates(openedAt, dueDate);
        return JSON.stringify({
            valid: check.valid,
            daysToDue: utils.calcDaysToDue(dueDate),
            leadDays: check.leadDays
        });
    },

    /**
     * Convert a value from the form to internal UTC Date/Time.
     * Accepts Date/Time (record form, user display format) or Date only (record producer Date variable);
     * a date-only value is treated as midday in the user's own time zone so its calendar day never shifts.
     */
    _toInternal: function(value) {
        if (!value)
            return '';
        var gdt = new GlideDateTime();
        if (value.indexOf(':') == -1) {
            var date = value;
            if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
                var gd = new GlideDate();
                gd.setDisplayValue(value);
                date = gd.getValue();
            }
            if (!date)
                return '';
            gdt.setDisplayValueInternal(date + ' 12:00:00');
        } else {
            gdt.setDisplayValue(value);
        }
        return gdt.getValue() || '';
    },

    type: 'MgrHubAjax'
});
